WITH joined AS (SELECT src.*, b.email FROM accounts src LEFT JOIN customers b ON src.customer_id = b.id), cleaned AS (SELECT *, CASE WHEN account_type IN ('CHECKING', 'CREDIT') THEN 'Core' ELSE 'Other' END AS account_type_group, DATE_FORMAT(opened_date, 'MMM yyyy') AS opened_date_label, COALESCE(status, 'DIRECT') AS status_filled FROM joined WHERE account_type NOT IN ('CREDIT', 'LOAN')), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY opened_date DESC NULLS LAST, id) AS rank_in_group FROM cleaned) x WHERE rank_in_group = 1) SELECT s.id, s.customer_id, s.account_type, s.balance, s.opened_date, s.status, s.account_type_group, s.opened_date_label, s.status_filled, (SELECT MIN(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS min_account_balance FROM deduped s ORDER BY min_account_balance NULLS LAST, status
